from flask import Flask, request, jsonify
import os
import json

app = Flask(__name__)

DATA_DIR = "/workdir/data"

if not os.path.exists(DATA_DIR):
    os.makedirs(DATA_DIR)

queues = {}


def load_queue(name):
    """Load queue from disk if it exists."""
    filepath = os.path.join(DATA_DIR, f"{name}.json")
    if os.path.exists(filepath):
        with open(filepath, 'r') as f:
            return json.load(f)["messages"]
    return []


def save_queue(name, messages):
    """Save queue to disk."""
    filepath = os.path.join(DATA_DIR, f"{name}.json")
    with open(filepath, 'w') as f:
        json.dump({"name": name, "messages": messages}, f)


@app.route("/queues", methods=["POST"])
def create_queue():
    data = request.get_json()
    if not data or "name" not in data:
        return jsonify({"error": "Missing name"}), 400
    queue_name = data["name"]
    if queue_name in queues:
        return jsonify({"error": "Queue already exists"}), 400
    queues[queue_name] = []
    save_queue(queue_name, queues[queue_name])
    return jsonify({"name": queue_name}), 201


@app.route("/queues/<name>/messages", methods=["POST"])
def send_message(name):
    if name not in queues:
        return jsonify({"error": "Queue not found"}), 404
    data = request.get_json()
    if not data or "content" not in data:
        return jsonify({"error": "Missing content"}), 400
    message = data["content"]
    queues[name].append(message)
    save_queue(name, queues[name])
    return jsonify({"content": message}), 201


@app.route("/queues/<name>/messages", methods=["GET"])
def receive_message(name):
    if name not in queues:
        return jsonify({"error": "Queue not found"}), 404
    if not queues[name]:
        return jsonify({}), 204
    # FIFO: pop first element
    msg = queues[name].pop(0)
    save_queue(name, queues[name])
    return jsonify({"content": msg}), 200


@app.route("/status", methods=["GET"])
def status():
    return jsonify({"status": "ok", "queues": list(queues.keys())}), 200


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000)
